UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Nefrologia / Quelante de Fósforo","pharmacological_class":"Sal de cálcio quelante de fosfato gastrointestinal","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"667 mg a 1334 mg (1 a 2 comprimidos)","interval_text":"8/8 horas (junto a cada refeição principal)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Tomar obrigatoriamente durante ou imediatamente antes das refeições principais para quelar o fósforo dietético.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Hipercalcemia, suspeita de toxicidade por digitálicos e litíase renal cálcica recorrente."],"renal_adjustment":"Avaliar taxa de filtração glomerular (TFG / ClCr). Ajustar dose ou intervalo em insuficiência renal moderada a grave conforme clearance.","hepatic_adjustment":"Usar com cautela em hepatopatias moderadas a graves; monitorar enzimas hepáticas periodicamente.","adverse_reactions":["Hipercalcemia, obstipação intestinal, náuseas e vômitos."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
