SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Anti-inflamatório e Imunossupressor","pharmacological_class":"Glicocorticoide sintético","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Infecções fúngicas sistêmicas não controladas.","Hipersensibilidade a corticosteroides.","Vacinação recente com vacinas de vírus vivos atenuados."],"renal_adjustment":"Sem necessidade de ajuste específico; monitorar retenção hidrossalina e pressão arterial.","hepatic_adjustment":"Usar com cautela em hepatopatias moderadas a graves; monitorar enzimas hepáticas periodicamente.","adverse_reactions":["Hiperglicemia, osteoporose, retenção de sódio/água, hipertensão arterial e insônia."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 3010;
